/**
 * Schemas for the messages of `google/protobuf/compiler/plugin.proto`, the
 * protocol between protoc or buf and code generator plugins.
 *
 * **Details**
 *
 * A plugin reads a `CodeGeneratorRequest` from standard input and writes a
 * `CodeGeneratorResponse` to standard output. Every message keeps the fields
 * it does not declare in its `[Protobuf.unknown]` property.
 *
 * The module is generated by `protoc-gen-effect` from the `plugin.proto` of
 * protoc 36.2.
 *
 * @stability experimental
 * @since 4.0.7
 */
import * as Schema from "../Schema.ts"
import * as Protobuf from "./Protobuf.ts"
import * as ProtobufDescriptor from "./ProtobufDescriptor.ts"

/**
 * The version number of protocol compiler.
 *
 * @stability experimental
 * @category schemas
 * @since 4.0.7
 */
export const Version = Protobuf.Message("google.protobuf.compiler.Version", {
  major: Schema.optionalKey(Protobuf.Int32).pipe(Protobuf.field(1)),
  minor: Schema.optionalKey(Protobuf.Int32).pipe(Protobuf.field(2)),
  patch: Schema.optionalKey(Protobuf.Int32).pipe(Protobuf.field(3)),
  /**
   * A suffix for alpha, beta or rc release, e.g., "alpha-1", "rc2". It should
   * be empty for mainline stable releases.
   */
  suffix: Schema.optionalKey(Schema.String).pipe(Protobuf.field(4, { validateUtf8: false }))
})
/**
 * The `google.protobuf.compiler.Version` message, as decoded by {@link Version}.
 *
 * @stability experimental
 * @category models
 * @since 4.0.7
 */
export interface Version extends Schema.Schema.Type<typeof Version> {}

/**
 * An encoded CodeGeneratorRequest is written to the plugin's stdin.
 *
 * @stability experimental
 * @category schemas
 * @since 4.0.7
 */
export const CodeGeneratorRequest = Protobuf.Message("google.protobuf.compiler.CodeGeneratorRequest", {
  /**
   * The .proto files that were explicitly listed on the command-line.  The
   * code generator should generate code only for these files.  Each file's
   * descriptor will be included in proto_file, below.
   */
  fileToGenerate: Schema.Array(Schema.String).pipe(Protobuf.field(1, { validateUtf8: false })),
  /**
   * The generator parameter passed on the command-line.
   */
  parameter: Schema.optionalKey(Schema.String).pipe(Protobuf.field(2, { validateUtf8: false })),
  /**
   * FileDescriptorProtos for all files in files_to_generate and everything
   * they import.  The files will appear in topological order, so each file
   * appears before any file that imports it.
   *
   * Note: the files listed in files_to_generate will include runtime-retention
   * options only, but all other files will include source-retention options.
   * The source_file_descriptors field below is available in case you need
   * source-retention options for files_to_generate.
   *
   * protoc guarantees that all proto_files will be written after
   * the fields above, even though this is not technically guaranteed by the
   * protobuf wire format.  This theoretically could allow a plugin to stream
   * in the FileDescriptorProtos and handle them one by one rather than read
   * the entire set into memory at once.  However, as of this writing, this
   * is not similarly optimized on protoc's end -- it will store all fields in
   * memory at once before sending them to the plugin.
   *
   * Type names of fields and extensions in the FileDescriptorProto are always
   * fully qualified.
   */
  protoFile: Schema.Array(ProtobufDescriptor.FileDescriptorProto).pipe(Protobuf.field(15)),
  /**
   * File descriptors with all options, including source-retention options.
   * These descriptors are only provided for the files listed in
   * files_to_generate.
   */
  sourceFileDescriptors: Schema.Array(ProtobufDescriptor.FileDescriptorProto).pipe(Protobuf.field(17)),
  /**
   * The version number of protocol compiler.
   */
  compilerVersion: Schema.optionalKey(Version).pipe(Protobuf.field(3))
})
/**
 * The `google.protobuf.compiler.CodeGeneratorRequest` message, as decoded by {@link CodeGeneratorRequest}.
 *
 * @stability experimental
 * @category models
 * @since 4.0.7
 */
export interface CodeGeneratorRequest extends Schema.Schema.Type<typeof CodeGeneratorRequest> {}

/**
 * Represents a single generated file.
 *
 * @stability experimental
 * @category schemas
 * @since 4.0.7
 */
export const CodeGeneratorResponse_File = Protobuf.Message("google.protobuf.compiler.CodeGeneratorResponse.File", {
  /**
   * The file name, relative to the output directory.  The name must not
   * contain "." or ".." components and must be relative, not be absolute (so,
   * the file cannot lie outside the output directory).  "/" must be used as
   * the path separator, not "\".
   *
   * If the name is omitted, the content will be appended to the previous
   * file.  This allows the generator to break large files into small chunks,
   * and allows the generated text to be streamed back to protoc so that large
   * files need not reside completely in memory at one time.  Note that as of
   * this writing protoc does not optimize for this -- it will read the entire
   * CodeGeneratorResponse before writing files to disk.
   */
  name: Schema.optionalKey(Schema.String).pipe(Protobuf.field(1, { validateUtf8: false })),
  /**
   * If non-empty, indicates that the named file should already exist, and the
   * content here is to be inserted into that file at a defined insertion
   * point.  This feature allows a code generator to extend the output
   * produced by another code generator.  The original generator may provide
   * insertion points by placing special annotations in the file that look
   * like:
   *   @@protoc_insertion_point(NAME)
   * The annotation can have arbitrary text before and after it on the line,
   * which allows it to be placed in a comment.  NAME should be replaced with
   * an identifier naming the point -- this is what other generators will use
   * as the insertion_point.  Code inserted at this point will be placed
   * immediately above the line containing the insertion point (thus multiple
   * insertions to the same point will come out in the order they were added).
   * The double-@ is intended to make it unlikely that the generated code
   * could contain things that look like insertion points by accident.
   *
   * For example, the C++ code generator places the following line in the
   * .pb.h files that it generates:
   *   // @@protoc_insertion_point(namespace_scope)
   * This line appears within the scope of the file's package namespace, but
   * outside of any particular class.  Another plugin can then specify the
   * insertion_point "namespace_scope" to generate additional classes or
   * other declarations that should be placed in this scope.
   *
   * Note that if the line containing the insertion point begins with
   * whitespace, the same whitespace will be added to every line of the
   * inserted text.  This is useful for languages like Python, where
   * indentation matters.  In these languages, the insertion point comment
   * should be indented the same amount as any inserted code will need to be
   * in order to work correctly in that context.
   *
   * The code generator that generates the initial file and the one which
   * inserts into it must both run as part of a single invocation of protoc.
   * Code generators are executed in the order in which they appear on the
   * command line.
   *
   * If |insertion_point| is present, |name| must also be present.
   */
  insertionPoint: Schema.optionalKey(Schema.String).pipe(Protobuf.field(2, { validateUtf8: false })),
  /**
   * The file contents.
   */
  content: Schema.optionalKey(Schema.String).pipe(Protobuf.field(15, { validateUtf8: false })),
  /**
   * Information describing the file content being inserted. If an insertion
   * point is used, this information will be appropriately offset and inserted
   * into the code generation metadata for the generated files.
   */
  generatedCodeInfo: Schema.optionalKey(ProtobufDescriptor.GeneratedCodeInfo).pipe(Protobuf.field(16))
})
/**
 * The `google.protobuf.compiler.CodeGeneratorResponse.File` message, as decoded by {@link CodeGeneratorResponse_File}.
 *
 * @stability experimental
 * @category models
 * @since 4.0.7
 */
export interface CodeGeneratorResponse_File extends Schema.Schema.Type<typeof CodeGeneratorResponse_File> {}

/**
 * The plugin writes an encoded CodeGeneratorResponse to stdout.
 *
 * @stability experimental
 * @category schemas
 * @since 4.0.7
 */
export const CodeGeneratorResponse = Protobuf.Message("google.protobuf.compiler.CodeGeneratorResponse", {
  /**
   * Error message.  If non-empty, code generation failed.  The plugin process
   * should exit with status code zero even if it reports an error in this way.
   *
   * This should be used to indicate errors in .proto files which prevent the
   * code generator from generating correct code.  Errors which indicate a
   * problem in protoc itself -- such as the input CodeGeneratorRequest being
   * unparseable -- should be reported by writing a message to stderr and
   * exiting with a non-zero status code.
   */
  error: Schema.optionalKey(Schema.String).pipe(Protobuf.field(1, { validateUtf8: false })),
  /**
   * A bitmask of supported features that the code generator supports.
   * This is a bitwise "or" of values from the Feature enum.
   */
  supportedFeatures: Schema.optionalKey(Protobuf.UInt64).pipe(Protobuf.field(2)),
  /**
   * The minimum edition this plugin supports.  This will be treated as an
   * Edition enum, but we want to allow unknown values.  It should be specified
   * according the edition enum value, *not* the edition number.  Only takes
   * effect for plugins that have FEATURE_SUPPORTS_EDITIONS set.
   */
  minimumEdition: Schema.optionalKey(Protobuf.Int32).pipe(Protobuf.field(3)),
  /**
   * The maximum edition this plugin supports.  This will be treated as an
   * Edition enum, but we want to allow unknown values.  It should be specified
   * according the edition enum value, *not* the edition number.  Only takes
   * effect for plugins that have FEATURE_SUPPORTS_EDITIONS set.
   */
  maximumEdition: Schema.optionalKey(Protobuf.Int32).pipe(Protobuf.field(4)),
  file: Schema.Array(CodeGeneratorResponse_File).pipe(Protobuf.field(15))
})
/**
 * The `google.protobuf.compiler.CodeGeneratorResponse` message, as decoded by {@link CodeGeneratorResponse}.
 *
 * @stability experimental
 * @category models
 * @since 4.0.7
 */
export interface CodeGeneratorResponse extends Schema.Schema.Type<typeof CodeGeneratorResponse> {}

/**
 * Sync with code_generator.h.
 *
 * @stability experimental
 * @category schemas
 * @since 4.0.7
 */
export const CodeGeneratorResponse_Feature = Protobuf.Enum("google.protobuf.compiler.CodeGeneratorResponse.Feature", {
  FEATURE_NONE: 0,
  FEATURE_PROTO3_OPTIONAL: 1,
  FEATURE_SUPPORTS_EDITIONS: 2
})

/**
 * The values of the `google.protobuf.compiler.CodeGeneratorResponse.Feature` enum.
 *
 * @stability experimental
 * @category models
 * @since 4.0.7
 */
export type CodeGeneratorResponse_Feature = typeof CodeGeneratorResponse_Feature.Type

/**
 * The messages and extensions of `google/protobuf/compiler/plugin.proto` and of its imports, for `Protobuf.anyUnpack`.
 *
 * @stability experimental
 * @category registries
 * @since 4.0.7
 */
export const registry = Protobuf.registry(
  Version,
  CodeGeneratorRequest,
  CodeGeneratorResponse,
  CodeGeneratorResponse_File,
  ProtobufDescriptor.registry
)
